const BREATH=`<g class="pj-exchange pj-breath" aria-hidden="true"><circle class="pj-p co2" cx="11" cy="-71" r="1.9" style="--d:0s"/><circle class="pj-p co2" cx="14" cy="-66" r="1.6" style="--d:1.3s"/><circle class="pj-p co2" cx="9" cy="-74" r="1.5" style="--d:2.4s"/></g>`;
